import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第97章 四个小时","description":"","frontmatter":{},"headers":[],"relativePath":"第97章_四个小时.md","filePath":"第97章_四个小时.md"}'),o={name:"第97章_四个小时.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第97章-四个小时" tabindex="-1">第97章 四个小时 <a class="header-anchor" href="#第97章-四个小时" aria-label="Permalink to &quot;第97章 四个小时&quot;">​</a></h1><p>那年十二月，我要在她的城市转机，四小时。</p><p>这件事是她先提出来的。</p><p>她说，你下个月要飞那边，你在宁城转。</p><p>我说，你怎么知道。</p><p>她说，你跟我讲过三次。</p><p>她说，你说你要去那边做一个短期，你说完又说买哪一班便宜。</p><p>她说，你把那个中转时间截了图给我看过一次。</p><p>我说，那你什么意思。</p><p>她说，我的意思是，那天我可以去接你。</p><p>我说，为什么。</p><p>她说，因为你四小时出不来。</p><p>她说，我说的是我在你那个机场里面等你。</p><p>我说，里面？</p><p>她说，里面不用出去。</p><p>她说，你转机不用签证，你在里面那个大厅坐着也是坐着。</p><p>她说，我在那儿陪你坐两小时。</p><p>我说，你那天不忙？</p><p>她说，我那天没课。</p><p>我说，你有图要交。</p><p>她说，我把本子带上。</p><p>她说，你坐在那儿我画，你不用跟我讲话。</p><p>她说，你也不用看我。</p><p>我说，那我们算什么。</p><p>她说，算你在机场里有一个人。</p><p>她说，你这个人四年没在机场里有人过。</p><p>她说，去年你走的时候在机场里坐了三小时，你给我发的是&quot;这里好吵&quot;。</p><p>我说，你记得。</p><p>她说，我什么都记得，我只是不讲。</p><p>她说，我这次讲是因为这次我能去。</p><p>我说，那我看看。</p><p>她说，你别看，你就说好。</p><p>我说，好。</p><p>那天我提前一天到了澄江北站。</p><p>我把包收拾了一遍。</p><p>我妈那天在门口站了一下。</p><p>她说，你这次去哪儿。</p><p>我说，我去办一个东西，我在中间转一下车。</p><p>她说，要几天。</p><p>我说，两天。</p><p>她说，你转车那个地方远不远。</p><p>我说，不算远。</p><p>我妈说，你带那件外套。</p><p>我说，我带了。</p><p>她说，你带那个本子干什么。</p><p>她说，你每次出门你都塞一个本子。</p><p>我说，我记东西。</p><p>她说，你记什么。</p><p>我说，我记路上。</p><p>我妈那天在门口站着，她手里拿着一个袋子。</p><p>她把袋子递给我。</p><p>里面是四个煮鸡蛋，和两个面包。</p><p>她说，你在车上不好买。</p><p>我说，机场能买。</p><p>她说，机场贵。</p><p>她说，你这个人你身上那点钱你算得比谁都清。</p><p>我说，我算不过一个人。</p><p>我妈说，谁。</p><p>我说，没有。</p><p>我妈把门推开一点，她看了我一会儿。</p><p>她说，你去转车那个地方，是不是有人。</p><p>我说，有。</p><p>我妈没再问。</p><p>她把门带上。</p><p>那天晚上我在火车上给她发了一句。</p><p>我说，我妈问我了。</p><p>她说，她问什么。</p><p>我说，她说是不是有人。</p><p>她说，你怎么说。</p><p>我说，我说有。</p><p>她隔了很久。</p><p>然后她说了一句。</p><p>她说，你今年讲&quot;有&quot;讲得比去年快。</p><p>她说，去年你讲&quot;没有&quot;。</p><p>我说，去年没有。</p><p>她说，去年也没有？</p><p>我说，去年没有人在机场。</p><p>她说，那你今年有。</p><p>我说，今年有。</p><p>她说，好。</p><p>她说，那我们后天见。</p><p>那两天里我做了一件事，一件我自己都没想到的事。</p><p>我把要跟她讲的话写了一遍。</p><p>我写在本子上。</p><p>我写了四行。</p><p>第一行：你今天瘦了。</p><p>第二行：你那个展我看过了，那张蓝的窗是歪的。</p><p>第三行：我今年没考上，我不考第二年了。</p><p>第四行：我下个月去上班。</p><p>第四行我自己看着奇怪。</p><p>因为我今年三月跟她讲过我不去工作，我要再考一年。</p><p>后来我四月改了主意。</p><p>我一直没告诉她。</p><p>我怕她问我为什么改。</p><p>我真正的理由我讲不出口。</p><p>理由是我算了一下，我今年二十一，我手上零，我拿什么再考一年。</p><p>我妈那年一月把家里那点定期跟我讲了。</p><p>她不是让我拿。</p><p>她是怕我不知道。</p><p>她讲完那天晚上我在楼下坐了一个钟头。</p><p>第二天我把报名改了。</p><p>我把那四行字看了三遍。</p><p>我把第一行划掉了。</p><p>划掉的原因是：她瘦了她自己知道，我讲一句“你今天瘦了”就是把一件她每天都在算的事递给她。</p><p>我把第二行也划掉了。</p><p>因为那张图她自己已经跟我讲过三次窗是歪的。</p><p>我最后留了两行。</p><p>那两行我要当面讲。</p><p>后天早上她六点发消息以前，我在机场里坐了三个钟头。</p><p>那三个钟头里我把那两行字在嘴里念了得四十遍。</p><p>我念到后来，我自己不确定那两行字是不是我写的。</p><p>机场那个 B 口那一排椅子，扶手是铁的。</p><p>我旁边坐了一个男的，四十多岁，他拿一个保温杯，他每四十分钟去接一次热水。</p><p>他第三次接水回来的时候坐到我旁边。</p><p>他说，你也转机。</p><p>我说，嗯。</p><p>他说，你去哪儿。</p><p>我说，飞一下午。</p><p>他说，你这趟出去几天。</p><p>我说，两天。</p><p>他说，家里人不担心。</p><p>我说，知道。</p><p>他“哦”了一声。</p><p>后来他说了一句。</p><p>他说，你是去见一个人吧。</p><p>我说，不是。</p><p>他说，不是你不会带四个鸡蛋。</p><p>他说，你那个包拉开一个缝，我看到了。</p><p>他说，你这种我在机场见多了。</p><p>他说，你们这种人坐下来不看手机，你每三分钟看一次。</p><p>我说，我等个人。</p><p>他说，等人不坐第三排。</p><p>他说，等人的坐在那个门口，你坐得远。</p><p>他说，你怕你看见她你先站起来。</p><p>我看着那个人。</p><p>他说完他拿起保温杯走了。</p><p>那天上午十一点，我去了一次卫生间。</p><p>我在镜子前面站了一会儿。</p><p>我对着镜子讲了一句话。</p><p>我讲的是：你今天瘦了。</p><p>我讲完自己听，我听得出来那不是人话。</p><p>因为那个声音很轻，而且它带着笑。</p><p>一个人在镜子前面讲一句关心人的话，他会不自觉把尾音挑上去，为了让自己看起来不紧张。</p><p>我听了三遍。</p><p>我把那一句划掉，我重新拿了一句。</p><p>我拿的是：你那三张图里，那张窗是歪的。</p><p>这一句我在镜子里讲得很好。</p><p>因为这一句不需要表情，它是一句陈述。</p><p>我那天在镜子前面站了六分钟。</p><p>我出来的时候，旁边那个人看了我一眼。</p><p>他看的是我手里那个空纸杯。</p><p>我拿着一个空纸杯，在镜子前面站了六分钟。</p><p>我那时候已经把那四句话删到只剩两句。</p><p>后来那两句我也没讲。</p><p>因为六点零七分那一条进来，我在心里把四句全忘了。</p><p>我只记得我在镜子前面听过自己讲话。</p><p>我去接了第四次热水。</p><p>我拿着那个纸杯站在 B 口的门口。</p><p>我站了得有两分钟。</p><p>后来六点零四分，屏幕上弹进来那一句。</p><p>她说，我今天来不了。</p>',161)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
